INSERT INTO public.questions (materia, topico, enunciado, alternativas, correta, explicacao) VALUES
('Estatística e Análise de Dados','Média aritmética','As notas de um candidato em 4 simulados foram 4,0; 6,0; 8,0 e 10,0. A média é','["7,0","6,5","8,0","7,5","6,0"]',0,'(4 + 6 + 8 + 10) / 4 = 28 / 4 = 7,0.'),
('Estatística e Análise de Dados','Mediana','O rol 2, 4, 6, 8 tem mediana igual a','["5","6","4","7","8"]',0,'Com número par de valores, a mediana é a média dos dois centrais: (4 + 6) / 2 = 5.'),
('Estatística e Análise de Dados','Moda','A moda do conjunto 2, 3, 3, 5, 7, 7, 7 é','["7","3","5","2","6"]',0,'7 é o valor de maior frequência, aparecendo 3 vezes.'),
('Estatística e Análise de Dados','Amplitude','A amplitude da série 12, 18, 25, 30, 45 é','["33","45","30","23","18"]',0,'Amplitude = maior valor menos menor valor = 45 - 12 = 33.'),
('Estatística e Análise de Dados','Dispersão','Somando-se 5 a cada valor de uma série, a média e o desvio padrão se comportam da seguinte forma:','["a média aumenta 5 e o desvio padrão não muda","a média e o desvio padrão aumentam 5","a média não muda e o desvio padrão aumenta 5","a média aumenta 5 e o desvio padrão diminui 5","média e desvio padrão não mudam"]',0,'Somar uma constante desloca a média, mas não altera a dispersão dos dados.'),
('Estatística e Análise de Dados','Razões e proporções','De 400 ocorrências registradas, 120 foram solucionadas. O percentual de solução é','["30%","25%","33%","40%","12%"]',0,'120 dividido por 400 = 0,30 = 30%.'),
('Estatística e Análise de Dados','Correlação','Havendo correlação positiva forte entre horas de estudo e nota obtida, pode-se afirmar que','["quanto maiores as horas de estudo, maior tende a ser a nota","o estudo determina sempre a nota obtida","quanto maiores as horas de estudo, menor a nota","não há relação entre as duas variáveis","a correlação prova relação de causa e efeito"]',0,'Correlação positiva indica movimento na mesma direção e não implica causalidade.'),
('Estatística e Análise de Dados','Interpretação de tabelas','Em um gráfico de setores, 25% das ocorrências correspondem a furto. Sendo o total de 800 ocorrências, o número de furtos é','["200","160","250","320","120"]',0,'800 x 0,25 = 200.'),
('Contabilidade e Análise Financeira','Patrimônio líquido','Uma repartição pública possui Ativo de 500.000 reais e Passivo de 180.000 reais. O Patrimônio Líquido é de','["320.000 reais","680.000 reais","180.000 reais","500.000 reais","220.000 reais"]',0,'Patrimônio líquido é a diferença entre ativo e passivo.'),
('Contabilidade e Análise Financeira','Regime de competência','Pelo regime de competência, a despesa é registrada quando','["ocorre o fato gerador, ainda que o pagamento seja posterior","é efetuado o pagamento em dinheiro","o gestor autoriza o empenho","o caixa fica negativo","é arquivada a documentação"]',0,'No regime de competência reconhece-se o fato no período em que ocorre, independentemente do pagamento.'),
('Contabilidade e Análise Financeira','Elementos patrimoniais','Representam obrigações com terceiros:','["o passivo","o ativo","o patrimônio líquido","as receitas","as despesas"]',0,'O passivo reúne as obrigações; o ativo reúne bens e direitos.'),
('Contabilidade e Análise Financeira','Depreciação','Sobre depreciação, é correto afirmar que','["reconhece a perda de valor de bens tangíveis pelo uso ou pelo decurso do tempo","é aplicada aos terrenos","atinge apenas o ativo circulante","representa uma receita para a entidade","só ocorre em bens alugados de terceiros"]',0,'Deprecia-se o bem de uso e de exploração; terrenos não se depreciam.'),
('Contabilidade e Análise Financeira','Resultado do exercício','O resultado do exercício resulta de','["receitas menos despesas","ativos menos passivos","vendas menos estoque","caixa menos bancos","lucro menos prejuízos acumulados"]',0,'A demonstração do resultado confronta receitas e despesas do período.'),
('Contabilidade e Análise Financeira','Princípios contábeis','O princípio da entidade determina que','["o patrimônio da entidade não se confunde com o dos sócios","a moeda funcional deve ser sempre o real","as receitas devem ser antecipadas","os gastos devem ser registrados apenas em dinheiro","a entidade deve antecipar despesas futuras"]',0,'A entidade é contabilmente separada da pessoa dos sócios.'),
('Contabilidade e Análise Financeira','Demonstrações contábeis','A demonstração que retrata a situação patrimonial da entidade em uma data é','["o balanço patrimonial","a demonstração do resultado do exercício","a demonstração dos fluxos de caixa","o relatório de gestão","a demonstração das mutações do patrimônio líquido"]',0,'O balanço patrimonial é estático e refere-se a uma data.'),
('Contabilidade e Análise Financeira','Ativo','São exemplos de ativo:','["caixa, veículos e contas a receber","fornecedores, salários a pagar e financiamentos","capital social e reservas","receitas de serviços","impostos a recolher"]',0,'Bens e direitos compõem o ativo; obrigações compõem o passivo.'),
('Informática','Excel','No Excel, a fórmula =SOMA(A1:A5) serve para','["somar os valores das células A1 até A5","contar as células numeradas de A1 a A5","exibir o maior valor de A1 a A5","calcular a média de A1 a A5","multiplicar A1 por A5"]',0,'A função SOMA acumula os valores do intervalo informado.'),
('Informática','Excel','A função PROCV é usada para','["procurar um valor na primeira coluna de uma tabela e devolver o conteúdo de outra coluna","somar valores que atendem a um critério","inverter a ordem dos dados da planilha","contar células vazias","ordenar uma lista alfabeticamente"]',0,'O PROCV procura na primeira coluna e retorna o valor da coluna indicada.'),
('Informática','Excel','Ao copiar uma fórmula que contém o endereço $B$1 para outra célula, esse endereço','["permanece fixo, referenciando sempre a célula B1","é ajustado para a nova linha","é ajustado para a nova coluna","é transformado em erro de referência","se torna relativo"]',0,'O sinal de dólar trava linha e coluna, criando referência absoluta.'),
('Informática','Excel','A mensagem de erro #VALOR! indica','["fórmula que recebeu tipo de dado inadequado para o cálculo","célula de referência apagada","nome de função desconhecido","intervalo inexistente","divisão por zero"]',0,'Erro de tipo de dado; divisão por zero gera #DIV/0! e nome inválido gera #NOME?.'),
('Informática','Excel','A estrutura correta da função condicional SE é','["=SE(teste lógico; valor se verdadeiro; valor se falso)","=SE(valor se verdadeiro; teste lógico)","=SE(teste lógico; valor se falso)","=SE(enquanto; valor)","=SE(soma; média)"]',0,'A função recebe o teste e os dois resultados possíveis, separados por ponto e vírgula.'),
('Informática','Excel','A função CONT.SE serve para','["contar células que atendem a um critério informado","somar células que atendem a um critério","calcular a média de um intervalo","localizar um valor em uma tabela","contar todas as células vazias"]',0,'CONT.SE conta quantas células satisfazem o critério; a soma condicionada é feita pela SOMA.SE.'),
('Informática','Word','No Word, o atalho Ctrl+B serve para','["salvar o documento","imprimir o documento","colocar o texto em negrito","colar o conteúdo da área de transferência","desfazer a última ação"]',0,'Ctrl+B salva; negrito é Ctrl+G, imprimir é Ctrl+P, colar é Ctrl+V e desfazer é Ctrl+Z.'),
('Informática','Windows','No Windows, a combinação Shift+Delete ao excluir um arquivo','["remove o arquivo sem enviá-lo para a lixeira","envia o arquivo para a lixeira","compacta o arquivo","renomeia o arquivo","oculta o arquivo"]',0,'A exclusão é definitiva, sem passagem pela lixeira.'),
('Informática','Segurança da informação','O golpe em que o criminoso envia mensagens que imitam instituições confiáveis para colher senhas e dados pessoais é chamado','["phishing","backup","firewall","compactação","desfragmentação"]',0,'O phishing usa engenharia social para induzir a vítima a entregar credenciais.'),
('Informática','Segurança da informação','O tipo de malware que cifra ou bloqueia arquivos e exige pagamento para liberá-los é o','["ransomware","adware","navegador","cache","compressor"]',0,'O ransomware sequestra os dados; backup testado e em mídia separada é a principal defesa.'),
('Informática','Backup','Sobre backup, é correto afirmar que','["o backup completo copia todos os dados selecionados e o incremental copia apenas o que mudou desde o último backup","o backup incremental apaga a cópia anterior","o backup em nuvem dispensa verificação das cópias","o backup deve ser armazenado no mesmo disco dos arquivos originais","o backup só pode ser feito semanalmente"]',0,'Cópias em mídia separada e verificadas são a regra de segurança.'),
('Informática','Internet','O cadeado e o prefixo https na barra de endereços de um site indicam','["conexão criptografada entre o navegador e o servidor","garantia de que o conteúdo publicado é verdadeiro","ausência de vírus no dispositivo","que o site pertence ao governo","que a página é gratuita"]',0,'O HTTPS protege o canal de comunicação, mas não atesta a idoneidade do site.'),
('Informática','Correio eletrônico','O campo Cco de uma mensagem de e-mail','["envia cópia da mensagem sem que os demais destinatários vejam o endereço","oculta o assunto da mensagem","impede o encaminhamento da mensagem","cifra o texto enviado","funciona como anexo"]',0,'Cc é cópia visível; Cco é cópia oculta aos demais destinatários.'),
('Informática','Compactação','A compactação de arquivos em formato zip tem por finalidade','["reduzir o tamanho dos arquivos para armazenagem ou envio","proteger a senha do usuário","eliminar vírus existentes","aumentar a velocidade do processador","criar backup automático"]',0,'Compactar economiza espaço e facilita a transferência dos arquivos.')
